#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int N;
vector<vector<int>> adj;

void get_dist(int start, vector<int>& dist) {
    dist.assign(N + 1, -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int count_at_depth(int u, int p, int d) {
    if (d == 0) return 1;
    int cnt = 0;
    for (int v : adj[u]) {
        if (v != p) {
            cnt += count_at_depth(v, u, d - 1);
        }
    }
    return cnt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> N)) return 0;

    adj.resize(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> dist1;
    get_dist(1, dist1);

    int A = 1;
    for (int i = 1; i <= N; ++i) {
        if (dist1[i] > dist1[A]) {
            A = i;
        }
    }

    vector<int> distA;
    get_dist(A, distA);

    int B = A;
    for (int i = 1; i <= N; ++i) {
        if (distA[i] > distA[B]) {
            B = i;
        }
    }

    int D = distA[B];
    vector<int> distB;
    get_dist(B, distB);

    long long ways = 0;

    if (D % 2 == 0) {
        int C = -1;
        for (int i = 1; i <= N; ++i) {
            if (distA[i] == D / 2 && distB[i] == D / 2) {
                C = i;
                break;
            }
        }

        vector<long long> counts;
        for (int v : adj[C]) {
            counts.push_back(count_at_depth(v, C, D / 2 - 1));
        }

        long long sum = 0;
        long long sum_sq = 0;
        for (long long c : counts) {
            sum += c;
            sum_sq += c * c;
        }
        ways = (sum * sum - sum_sq) / 2;
    } else {
        int C1 = -1, C2 = -1;
        for (int i = 1; i <= N; ++i) {
            if (distA[i] == D / 2 && distB[i] == D / 2 + 1) {
                C1 = i;
            }
            if (distA[i] == D / 2 + 1 && distB[i] == D / 2) {
                C2 = i;
            }
        }

        long long c1 = count_at_depth(C1, C2, D / 2);
        long long c2 = count_at_depth(C2, C1, D / 2);
        ways = c1 * c2;
    }

    cout << D + 1 << "\n";
    cout << ways << "\n";

    return 0;
}
